e = 16, fireRate = 0.05, magSize = 30, reloadTime = 1.7, recoil = 0.7, range = 110, spread = 0.032},\n			["P90"] = {damage = 17, fireRate = 0.055, magSize = 50, reloadTime = 2.2, recoil = 0.6, range = 120, spread = 0.035},\n			["CBJ-MS"] = {damage = 19, fireRate = 0.07, magSize = 30, reloadTime = 1.8, recoil = 0.8, range = 125, spread = 0.03},\n			["MX4"] = {damage = 20, fireRate = 0.075, magSize = 30, reloadTime = 1.9, recoil = 0.85, range = 130, spread = 0.028},\n			["MPX"] = {damage = 22, fireRate = 0.08, magSize = 30, reloadTime = 1.9, recoil = 0.9, range = 135, spread = 0.026},\n		},\n	},\n	Handguns = {\n		name = "Пистолеты",\n		weapons = {\n			["M1911"] = {damage = 30, fireRate = 0.2, magSize = 12, reloadTime = 1.5, recoil = 1.5, range = 80, spread = 0.04},\n			["Glock 17"] = {damage = 22, fireRate = 0.12, magSize = 17, reloadTime = 1.3, recoil = 1.0, range = 70, spread = 0.045},\n			["Desert Eagle"] = {damage = 50, fireRate = 0.3, magSize = 7, reloadTime = 1.8, recoil = 2.5, range = 100, spread = 0.035},\n			[".357 (Default, Speedloader Included)"] = {damage = 55, fireRate = 0.4, magSize = 6, reloadTime = 2.5, recoil = 3.0, range = 90, spread = 0.03, revolver = true},\n			["P226"] = {damage = 25, fireRate = 0.15, magSize = 15, reloadTime = 1.4, recoil = 1.2, range = 75, spread = 0.042},\n			["M9"] = {damage = 24, fireRate = 0.13, magSize = 15, reloadTime = 1.3, recoil = 1.1, range = 70, spread = 0.043},\n			["CZ-75"] = {damage = 26, fireRate = 0.14, magSize = 16, reloadTime = 1.4, recoil = 1.15, range = 75, spread = 0.04},\n			["Deagle 44"] = {damage = 48, fireRate = 0.28, magSize = 8, reloadTime = 1.7, recoil = 2.3, range = 95, spread = 0.036},\n		},\n	},\n	MG = {\n		name = "Пулемёты",\n		weapons = {\n			["M249"] = {damage = 22, fireRate = 0.075, magSize = 100, reloadTime = 5.0, recoil = 1.8, range = 180, spread = 0.04},\n			["M60"] = {damage = 28, fireRate = 0.1, magSize = 100, reloadTime = 5.5, recoil = 2.2, range = 220, spread = 0.035},\n			["RPD"] = {damage = 25, fireRate = 0.09, magSize = 100, reloadTime = 5.0, recoil = 2.0, range = 200, spread = 0.038},\n			["RPK-74M"] = {damage = 26, fireRate = 0.1, magSize = 45, reloadTime = 3.0, recoil = 1.8, range = 200, spread = 0.032},\n			["MG4"] = {damage = 24, fireRate = 0.085, magSize = 100, reloadTime = 5.2, recoil = 1.9, range = 190, spread = 0.036},\n			["PKM (Default, Is it Reused from MWR?)"] = {damage = 30, fireRate = 0.11, magSize = 100, reloadTime = 5.5, recoil = 2.3, range = 230, spread = 0.034},\n			["Bruen MK9 (Default, BRU-DUH-DUH-DUH-DUH-DUH-DUH-DUH-DUH-DUH-DUH-DUH)"] = {damage = 23, fireRate = 0.08, magSize = 100, reloadTime = 5.0, recoil = 1.7, range = 185, spread = 0.037},\n			["Holger-26 (Default, GUH-DUH-DUH-DUH-DUH-DUH-DUH-DUH-DUH)"] = {damage = 22, fireRate = 0.075, magSize = 100, reloadTime = 5.0, recoil = 1.6, range = 180, spread = 0.038},\n			["M27"] = {damage = 24, fireRate = 0.085, magSize = 100, reloadTime = 5.0, recoil = 1.7, range = 190, spread = 0.035},\n		},\n	},\n}\n\nWeaponConfig.Attachments = {\n	Suppressors = {\n		{"Suppressor", soundReduction = 0.5, damagePenalty = -2, rangePenalty = -20},\n	},\n	Scopes = {\n		{"Red Dot", zoomMultiplier = 1.5, adsSpeed = 1.2},\n		{"ACOG", zoomMultiplier = 3.0, adsSpeed = 1.5},\n		{"Sniper Scope", zoomMultiplier = 6.0, adsSpeed = 1.8},\n	},\n	Grips = {\n		{"Vertical Grip", recoilReduction = 0.2},\n		{"Angled Grip", adsSpeedBonus = 0.15},\n	},\n	Stocks = {\n		{"Collapsed Stock", mobilityBonus = 0.1, stabilityPenalty = 0.1},\n		{"Heavy Stock", stabilityBonus = 0.15, mobilityPenalty = -0.05},\n	},\n	Barrels = {\n		{"Long Barrel", rangeBonus = 50, damageBonus = 3},\n		{"Short Barrel", rangePenalty = -30, mobilityBonus = 0.1},\n	},\n}\n\nWeaponConfig.PartNames = {\n	Barrel = {"Barrel", "barrel", "Barrel Base", "Cylinder Barrel", "Barrel Main", "Barrel Cover", "Flash Hider", "Muzzle"},\n	Bolt = {"Bolt", "Bolt Part", "Bolt Back", "Bolt Handle", "Bolt1", "Bolt2", "Charging Handle", "Bolt Extraction Handle", "Charge"},\n	Mag = {"Mag", "Magazine", "Drum", "Box Mag", "Box", "20 Round Magazine", "30 Round Magazine", "30rnd 5.56mm NATO Magazine", "20rnd 7.62mm NATO Magazine", "5rnd 7.62mm Rimmed Tactical Magazine"},\n	Stock = {"Stock", "Back Stock", "Stock Details", "Stock Part", "Stock Wire", "Buffer Tube", "Brace"},\n	Grip = {"Grip", "Pistol Grip", "FakeGrip", "VerticleGrip"},\n	Trigger = {"Trigger", "Trigger Guard", "Trigger Group", "Match Trigger"},\n	Body = {"Default", "MeshPart", "Body", "Main", "Receiver", "Recevier", "Base", "Frame", "Lower", "Upper"},\n	Slide = {"Slide", "Topper"},\n}\n\nfunction WeaponConfig:GetWeaponData(weaponName)\n	for categoryName, category in pairs(self.Categories) do\n		if category.weapons[weaponName] then\n			return category.weapons[weaponName], categoryName\n		end\n	end\n\n	local base = weaponName:match("^(.-)%s*%(") or weaponName\n	base = base:match("^(.-)%s*,") or base\n	base = base:gsub("%s+$", ""):gsub("^%s+", "")\n\n	for categoryName, category in pairs(self.Categories) do\n		if category.weapons[base] then\n			return category.weapons[base], categoryName\n		end\n	end\n\n	local lower = weaponName:lower()\n	for categoryName, category in pairs(self.Categories) do\n		for key, data in pairs(category.weapons) do\n			local keyLower = key:lower()\n			local keyBase = keyLower:match("^(.-)%s*%(") or keyLower\n			keyBase = keyBase:match("^(.-)%s*,") or keyBase\n			keyBase = keyBase:gsub("%s+$", "")\n			if lower:find(keyBase, 1, true) or keyBase:find(base:lower(), 1, true) then\n				return data, categoryName\n			end\n		end\n	end\n\n	return {damage = 25, fireRate = 0.1, magSize = 30, reloadTime = 2.2, recoil = 1.5, range = 180, spread = 0.02}, "Default"\nend\n\nfunction WeaponConfig:GetAllWeaponNames()\n	local names = {}\n	for _, category in pairs(self.Categories) do\n		for weaponName, _ in pairs(category.weapons) do\n			table.insert(names, weaponName)\n		end\n	end\n	return names\nend\n\nreturn WeaponConfig\n')
ensureModule(RS:WaitForChild('Modules'):WaitForChild('Weapon'), 'WeaponParser', 'ModuleScript', 'local ReplicatedStorage = game:GetService("ReplicatedStorage")\nlocal WeaponConfig = require(ReplicatedStorage.Modules.Weapon.WeaponConfig)\n\nlocal WeaponParser = {}\nWeaponParser.__index = WeaponParser\n\nlocal KEYWORDS = {\n	Barrel = {"barrel", "muzzle", "flash", "hider", "suppressor", "thread", "cylinder"},\n	Mag = {"mag", "magazine", "clip", "drum", "box", "round"},\n	Bolt = {"bolt", "charging", "handle", "charge", "slide"},\n	Stock = {"stock", "brace", "buffer", "tube", "back"},\n	Grip = {"grip", "handle", "hold"},\n	Body = {"receiver", "body", "frame", "lower", "upper", "main", "base", "default"},\n}\n\nlocal function findByNames(weaponModel, targetKey)\n	local names = WeaponConfig.PartNames[targetKey]\n	for _, name in ipairs(names) do\n		local found = weaponModel:FindFirstChild(name, true)\n		if found then\n			if found:IsA("Model") then\n				local base = found:FindFirstChild("Base") or found:FindFirstChildWhichIsA("MeshPart") or found:FindFirstChildWhichIsA("Part")\n				return base or found\n			end\n			return found\n		end\n	end\n	return nil\nend\n\nlocal function findByKeywords(weaponModel, targetKey, exclude)\n	local keywords = KEYWORDS[targetKey]\n	if not keywords then return nil end\n	for _, desc in ipairs(weaponModel:GetDescendants()) do\n		if (desc:IsA("MeshPart") or desc:IsA("Part")) and desc ~= exclude then\n			local lower = desc.Name:lower()\n			for _, kw in ipairs(keywords) do\n				if lower:find(kw, 1, true) then\n					return desc\n				end\n			end\n		end\n	end\n	return nil\nend\n\nlocal function getCenter(allParts)\n	local sum = Vector3.new(0, 0, 0)\n	for _, p in ipairs(allParts) do\n		sum = sum + p.Position\n	end\n	return sum / #allParts\nend\n\nlocal function findBarrelByGeometry(allParts, body)\n	if #allParts < 2 then return nil end\n\n	local minX, maxX = math.huge, -math.huge\n	local minZ, maxZ = math.huge, -math.huge\n	for _, p in ipairs(allParts) do\n		minX = math.min(minX, p.Position.X)\n		maxX = math.max(maxX, p.Position.X)\n		minZ = math.min(minZ, p.Position.Z)\n		maxZ = math.max(maxZ, p.Position.Z)\n	end\n\n	local axis = (maxX - minX) > (maxZ - minZ) and "X" or "Z"\n	local extreme = axis == "X" and maxX or maxZ\n	local threshold = axis == "X" and (maxX - minX) * 0.15 or (maxZ - minZ) * 0.15\n\n	local best, bestArea = nil, math.huge\n	for _, p in ipairs(allParts) do\n		local pos = axis == "X" and p.Position.X or p.Position.Z\n		if math.abs(pos - extreme) <= threshold then\n			local area = p.Size.X * p.Size.Y + p.Size.X * p.Size.Z + p.Size.Y * p.Size.Z\n			if area < bestArea then\n				bestArea = area\n				best = p\n			end\n		end\n	end\n\n	return best\nend\n\nlocal function findMagByGeometry(allParts, body)\n	if not body then return nil end\n	local bodyPos = body.Position\n\n	local best, bestDist = nil, math.huge\n	for _, p in ipairs(allParts) do\n		if p ~= body then\n			local offset = p.Position - bodyPos\n			if offset.Y < -0.3 then\n				local dist = math.sqrt(offset.X * offset.X + offset.Z * offset.Z)\n				if dist < bestDist then\n					bestDist = dist\n					best = p\n				end\n			end\n		end\n	end\n\n	return best\nend\n\nfunction WeaponParser:ParseWeapon(weaponModel)\n	local parts = {\n		barrel = nil,\n		bolt = nil,\n		mag = nil,\n		stock = nil,\n		grip = nil,\n		trigger = nil,\n		body = nil,\n		slide = nil,\n		allParts = {},\n		magPart = nil,\n		magModel = nil,\n	}\n\n	for _, desc in ipairs(weaponModel:GetDescendants()) do\n		if desc:IsA("MeshPart") or desc:IsA("Part") then\n			table.insert(parts.allParts, desc)\n		end\n	end\n\n	parts.barrel = findByNames(weaponModel, "Barrel")\n	parts.bolt = findByNames(weaponModel, "Bolt")\n	parts.stock = findByNames(weaponModel, "Stock")\n	parts.grip = findByNames(weaponModel, "Grip")\n	parts.trigger = findByNames(weaponModel, "Trigger")\n	parts.slide = findByNames(weaponModel, "Slide")\n\n	for _, name in ipairs(WeaponConfig.PartNames.Mag) do\n		local found = weaponModel:FindFirstChild(name, true)\n		if found then\n			if found:IsA("Model") then\n				parts.magModel = found\n				parts.mag = found:FindFirstChild("Base") or found:FindFirstChildWhichIsA("MeshPart") or found:FindFirstChildWhichIsA("Part")\n			else\n				parts.mag = found\n			end\n			break\n		end\n	end\n\n	for _, name in ipairs(WeaponConfig.PartNames.Body) do\n		local found = weaponModel:FindFirstChild(name, true)\n		if found and not found:IsA("Model") then\n			parts.body = found\n			break\n		end\n	end\n\n	if not parts.body then\n		for _, child in ipairs(weaponModel:GetChildren()) do\n			if child:IsA("MeshPart") then\n				parts.body = child\n				break\n			end\n		end\n	end\n\n	if not parts.body and #parts.allParts > 0 then\n		parts.body = parts.allParts[1]\n	end\n\n	if not parts.barrel then\n		parts.barrel = findByKeywords(weaponModel, "Barrel", parts.body)\n	end\n	if not parts.barrel and parts.body then\n		parts.barrel = findBarrelByGeometry(parts.allParts, parts.body)\n	end\n\n	if not parts.mag then\n		parts.mag = findByKeywords(weaponModel, "Mag", parts.body)\n	end\n	if not parts.mag and parts.body then\n		parts.mag = findMagByGeometry(parts.allParts, parts.body)\n	end\n\n	if not parts.stock then\n		parts.stock = findByKeywords(weaponModel, "Stock", parts.body)\n	end\n	if not parts.grip then\n		parts.grip = findByKeywords(weaponModel, "Grip", parts.body)\n	end\n	if not parts.bolt then\n		parts.bolt = findByKeywords(weaponModel, "Bolt", parts.body)\n	end\n\n	return parts\nend\n\nfunction WeaponParser:CreateHandle(weaponModel, parts)\n	local existing = weaponModel:FindFirstChild("Handle")\n	if existing then return existing end\n\n	local handleSource = parts.grip or parts.body\n	if not handleSource then return nil end\n\n	local handle = Instance.new("Part")\n	handle.Name = "Handle"\n	handle.Size = Vector3.new(0.2, 0.2, 0.2)\n	handle.CFrame = handleSource.CFrame\n	handle.Transparency = 1\n	handle.CanCollide = false\n	handle.Anchored = false\n	handle.Massless = true\n	handle.Parent = weaponModel\n\n	return handle\nend\n\nfunction WeaponParser:WeldAllParts(parts)\n	local base = parts.grip or parts.body\n	if not base then return end\n	for _, p in ipairs(parts.allParts) do\n		if p ~= base and p.Name ~= "Handle" then\n			local wc = Instance.new("WeldConstraint")\n			wc.Part0 = base\n			wc.Part1 = p\n			wc.Parent = p\n		end\n	end\nend\n\nfunction WeaponParser:CreateBarrelAttachment(weaponModel, parts)\n	local barrel = parts.barrel\n	if not barrel then return nil end\n\n	local attachment = Instance.new("Attachment")\n	attachment.Name = "MuzzleAttachment"\n	attachment.Parent = barrel\n\n	local offset = barrel.Size.Z / 2\n	attachment.CFrame = CFrame.new(0, 0, -offset)\n\n	return attachment\nend\n\nfunction WeaponParser:GetShootOrigin(weaponModel, parts)\n	local attachment = weaponModel:FindFirstChild("MuzzleAttachment", true)\n	if attachment then\n		return attachment.WorldCFrame.Position, attachment.WorldCFrame.LookVector\n	end\n\n	if parts.barrel then\n		local barrelCF = parts.barrel.CFrame\n		return barrelCF.Position + barrelCF.LookVector * (-parts.barrel.Size.Z / 2), barrelCF.LookVector\n	end\n\n	if parts.body then\n		local bodyCF = parts.body.CFrame\n		return bodyCF.Position + bodyCF.LookVector * (-bodyCF.Size.Z / 2), bodyCF.LookVector\n	end\n\n	return nil, nil\nend\n\nfunction WeaponParser:HideMagDuringReload(parts, hidden)\n	if parts.mag then\n		parts.mag.Transparency = hidden and 1 or 0\n	end\n	if parts.magModel then\n		for _, child in ipairs(parts.magModel:GetDescendants()) do\n			if child:IsA("MeshPart") or child:IsA("Part") then\n				child.Transparency = hidden and 1 or 0\n			end\n		end\n	end\nend\n\nreturn WeaponParser\n')
ensureModule(RS:WaitForChild('Modules'):WaitForChild('Weapon'), 'WeaponValidator', 'ModuleScript', 'local ReplicatedStorage = game:GetService("ReplicatedStorage")\nlocal WeaponConfig = require(ReplicatedStorage.Modules.Weapon.WeaponConfig)\nlocal WeaponParser = require(ReplicatedStorage.Modules.Weapon.WeaponParser)\n\nlocal WeaponValidator = {}\nWeaponValidator.__index = WeaponValidator\n\nfunction WeaponValidator:ValidateWeapon(weaponModel)\n	local parts = WeaponParser:ParseWeapon(weaponModel)\n	local result = {\n		name = weaponModel.Name,\n		hasBarrel = parts.barrel ~= nil,\n		hasMag = parts.mag ~= nil,\n		hasBody = parts.body ~= nil,\n		hasBolt = parts.bolt ~= nil,\n		hasStock = parts.stock ~= nil,\n		hasGrip = parts.grip ~= nil,\n		partsCount = #parts.allParts,\n		isUsable = false,\n		reasons = {},\n		warnings = {},\n	}\n\n	local weaponData = WeaponConfig:GetWeaponData(weaponModel.Name)\n	if not weaponData then\n		table.insert(result.reasons, "Нет конфига в WeaponConfig")\n		return result\n	end\n\n	if not result.hasBody then\n		table.insert(result.reasons, "Нет тела (Body)")\n	end\n\n	if not result.hasBarrel then\n		table.insert(result.warnings, "Нет Barrel (стрельба от Body)")\n	end\n\n	if not result.hasMag then\n		table.insert(result.warnings, "Нет Mag (перезарядка без анимации)")\n	end\n\n	if result.partsCount < 2 then\n		table.insert(result.reasons, "Слишком мало частей: " .. result.partsCount)\n	end\n\n	result.isUsable = #result.reasons == 0\n\n	return result\nend\n\nfunction WeaponValidator:ScanAll()\n	local report = {\n		usable = {},\n		unusable = {},\n		totalScanned = 0,\n		categories = {},\n	}\n\n	local function scanFolder(folder)\n		if not folder then return end\n		for _, weapon in ipairs(folder:GetChildren()) do\n			if weapon:IsA("Model") then\n				local result = self:ValidateWeapon(weapon)\n				report.totalScanned += 1\n\n				if result.isUsable then\n					table.insert(report.usable, result)\n				else\n					table.insert(report.unusable, result)\n				end\n			end\n		end\n	end\n\n	local workspaceFolders = {"AR\'s", "Rifles", "Handguns", "SMG\'s", "Machine Guns"}\n	for _, folderName in ipairs(workspaceFolders) do\n		local folder = workspace:FindFirstChild(folderName)\n		if folder then\n			report.categories[folderName] = {usable = 0, unusable = 0}\n			for _, weapon in ipairs(folder:GetChildren()) do\n				if weapon:IsA("Model") then\n					local result = self:ValidateWeapon(weapon)\n					report.totalScanned += 1\n\n					if result.isUsable then\n						table.insert(report.usable, result)\n						report.categories[folderName].usable += 1\n					else\n						table.insert(report.unusable, result)\n						report.categories[folderName].unusable += 1\n					end\n				end\n			end\n		end\n	end\n\n	return report\nend\n\nfunction WeaponValidator:PrintReport(report)\n	print("========== ОТЧЁТ ВАЛИДАЦИИ ОРУЖИЯ ==========")\n	print("Всего проверено: " .. report.totalScanned)\n	print("Работоспособных: " .. #report.usable)\n	print("Неработоспособных: " .. #report.unusable)\n	print("")\n\n	print("--- ПО КАТЕГОРИЯМ ---")\n	for catName, stats in pairs(report.categories) do\n		local total = stats.usable + stats.unusable\n		local percent = total > 0 and math.floor((stats.usable / total) * 100) or 0\n		print(catName .. ": " .. stats.usable .. "/" .. total .. " (" .. percent .. "%)")\n	end\n\n	print("")\n	print("--- РАБОТАЮЩЕЕ ОРУЖИЕ ---")\n	for _, weapon in ipairs(report.usable) do\n		local flags = {}\n		if weapon.hasBarrel then table.insert(flags, "BRL") end\n		if weapon.hasMag then table.insert(flags, "MAG") end\n		if weapon.hasBolt then table.insert(flags, "BLT") end\n		if weapon.hasStock then table.insert(flags, "STK") end\n		if weapon.hasGrip then table.insert(flags, "GRP") end\n		print("[OK] " .. weapon.name .. " | " .. weapon.partsCount .. " parts | " .. table.concat(flags, ", "))\n	end\n\n	print("")\n	print("--- НЕ РАБОТАЮЩЕЕ ОРУЖИЕ ---")\n	for _, weapon in ipairs(report.unusable) do\n		print("[X] " .. weapon.name .. " | Причины: " .. table.concat(weapon.reasons, "; "))\n	end\n\n	print("")\n	print("--- РАБОТАЮЩЕЕ С ПРЕДУПРЕЖДЕНИЯМИ ---")\n	for _, weapon in ipairs(report.usable) do\n		if weapon.warnings and #weapon.warnings > 0 then\n			print("[!] " .. weapon.name .. " | " .. table.concat(weapon.warnings, "; "))\n		end\n	end\n\n	print("")\n	print("========== КОНЕЦ ОТЧЁТА ==========")\nend\n\nfunction WeaponValidator:CreateHandles(report)\n	local created = 0\n	for _, weaponInfo in ipairs(report.usable) do\n		local weaponModel = self:FindWeaponModel(weaponInfo.name)\n		if weaponModel then\n			local parts = WeaponParser:ParseWeapon(weaponModel)\n			WeaponParser:CreateHandle(weaponModel, parts)\n			WeaponParser:CreateBarrelAttachment(weaponModel, parts)\n			created += 1\n		end\n	end\n	return created\nend\n\nfunction WeaponValidator:FindWeaponModel(name)\n	local folders = {"AR\'s", "Rifles", "Handguns", "SMG\'s", "Machine Guns"}\n	for _, folderName in ipairs(folders) do\n		local folder = workspace:FindFirstChild(folderName)\n		if folder then\n			local found = folder:FindFirstChild(name)\n			if found then return found end\n		end\n	end\n	return nil\nend\n\nfunction WeaponValidator:ExportReport(report)\n	local lines = {}\n\n	table.insert(lines, "VALIDATION REPORT - SFKU Weapons")\n	table.insert(lines, "================================")\n	table.insert(lines, "Total: " .. report.totalScanned)\n	table.insert(lines, "Usable: " .. #report.usable)\n	table.insert(lines, "Unusable: " .. #report.unusable)\n	table.insert(lines, "")\n\n	table.insert(lines, "CATEGORIES:")\n	for catName, stats in pairs(report.categories) do\n		local total = stats.usable + stats.unusable\n		local percent = total > 0 and math.floor((stats.usable / total) * 100) or 0\n		table.insert(lines, "  " .. catName .. ": " .. stats.usable .. "/" .. total .. " (" .. percent .. "%)")\n	end\n	table.insert(lines, "")\n\n	table.insert(lines, "USABLE WEAPONS:")\n	for _, weapon in ipairs(report.usable) do\n		table.insert(lines, "  [OK] " .. weapon.name)\n	end\n	table.insert(lines, "")\n\n	table.insert(lines, "UNUSABLE WEAPONS:")\n	for _, weapon in ipairs(report.unusable) do\n		table.insert(lines, "  [X] " .. weapon.name .. " - " .. table.concat(weapon.reasons, "; "))\n	end\n\n	return table.concat(lines, "\\n")\nend\n\nreturn WeaponValidator\n')
